    @{ Path = "操作系统/07_完整工作流/decision-checkpoint-判定细则.md"; Pattern = '外部工具战场|Codex\s*战场|Claude Code\s*战场|交接卡给\s*(Claude Code|Codex)|(?i:external-tool battlefield|Codex\s*battlefield|Claude Code\s*battlefield|handoff card to\s*(Claude Code|Codex))'; Label = "decision-checkpoint decision rules still assign responsibility by tool name" },
    @{ Path = "操作系统/01_架构/工具载体矩阵.md"; Pattern = '跨工具铁律|cross-tool mandatory rules'; Label = "Tool adapter matrix still describes the meta-rule pool as cross-tool mandatory rules" }
