$appLiteral = [regex]::Escape('{{APP_REPO_DIR}}')
foreach ($check in $script:P4kToolSubjectChecks) {
  $check.Pattern = $check.Pattern.Replace('__CZXT_APP_REPO_DIR_REGEX__', $appLiteral)
}
